/* File: style.css */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    font-family: system-ui, -apple-system, sans-serif;
}

body {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%);
}

.calculator {
    width: 320px;
    background: rgba(30, 41, 59, 0.85);
    backdrop-filter: blur(16px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 24px;
    padding: 20px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5);
}

.display {
    width: 100%;
    height: 70px;
    background: #0f172a;
    border-radius: 16px;
    color: #ffffff;
    font-size: 2.2rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 0 20px;
    margin-bottom: 20px;
    border: 1px solid rgba(255, 255, 255, 0.05);
}

.buttons {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
}

.btn {
    height: 55px;
    border-radius: 14px;
    border: none;
    background: #334155;
    color: #f8fafc;
    font-size: 1.25rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
}

.btn:hover {
    background: #475569;
}

.btn-operator {
    background: #4f46e5;
    color: #ffffff;
}

.btn-clear {
    background: #e11d48;
    color: #ffffff;
}

.btn-equals {
    background: #10b981;
    color: #ffffff;
    grid-row: span 2;
    height: 122px;
}

.btn-zero {
    grid-column: span 2;
}
